"""Shared rendering helpers."""

from __future__ import annotations

from dataclasses import dataclass, field

from dbss.introspection import Catalog
from dbss.utils.fs import normalize_newlines


@dataclass(frozen=True)
class RenderContext:
    """Settings every renderer needs besides the catalog being rendered."""

    migration_role: str
    baseline: Catalog  # platform state before any migration (defaults, built-in roles)


@dataclass
class RenderedObject:
    """One generated file's worth of SQL (or an error explaining why it cannot be generated)."""

    kind: str
    identity: str  # stable, unique within the kind, e.g. "public.profiles"
    filename: str  # file name inside the kind folder (already encoded)
    label: str  # human-readable object description, e.g. "table public.profiles"
    schema: str | None  # schema used for scope filtering (None = cluster-level object)
    statements: list[str] = field(default_factory=list)
    table: str | None = None  # owning table identity, for dependency reporting
    error: str | None = None

    @property
    def content(self) -> str:
        header = f"-- Generated by DBSS: {self.label}.\n-- Do not edit by hand; regenerate with `dbss update`.\n"
        body = "\n\n".join(s.rstrip() for s in self.statements)
        return normalize_newlines(header + "\n" + body + "\n")


def literal(value: str) -> str:
    """SQL string literal (standard_conforming_strings = on)."""
    return "'" + value.replace("'", "''") + "'"


def comment_on(target_kind: str, target: str, comment: str | None) -> list[str]:
    if comment is None:
        return []
    return [f"COMMENT ON {target_kind} {target} IS {literal(comment)};"]


def _outer_parens_balanced(expr: str) -> bool:
    """True when ``expr`` is wrapped in one pair of parentheses enclosing everything."""
    if not (expr.startswith("(") and expr.endswith(")")):
        return False
    depth = 0
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in ("'", '"'):
            quote = ch
            i += 1
            while i < n:
                if expr[i] == quote:
                    if i + 1 < n and expr[i + 1] == quote:
                        i += 2
                        continue
                    break
                i += 1
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0 and i != n - 1:
                return False
        i += 1
    return depth == 0


def parenthesize(expr: str) -> str:
    """Wrap an expression in parentheses unless it already is wrapped as a whole."""
    expr = expr.strip()
    return expr if _outer_parens_balanced(expr) else f"({expr})"


def owner_statement(object_kind: str, target: str, owner: str, migration_role: str) -> list[str]:
    """``ALTER ... OWNER TO`` only when the owner differs from the role migrations run as."""
    if owner == migration_role:
        return []
    return [f"ALTER {object_kind} {target} OWNER TO {quote_ident(owner)};"]


_RESERVED_LOWER_SAFE = set("abcdefghijklmnopqrstuvwxyz0123456789_")


def quote_ident(name: str) -> str:
    """Conservative identifier quoting (quotes anything that is not plain lower-case)."""
    if name and name[0] not in "0123456789" and all(c in _RESERVED_LOWER_SAFE for c in name) and name not in _KEYWORDS:
        return name
    return '"' + name.replace('"', '""') + '"'


# Reserved words that must be quoted as identifiers (subset sufficient for role/schema names).
_KEYWORDS = {
    "all", "analyse", "analyze", "and", "any", "array", "as", "asc", "asymmetric", "both", "case", "cast",
    "check", "collate", "column", "constraint", "create", "current_catalog", "current_date", "current_role",
    "current_time", "current_timestamp", "current_user", "default", "deferrable", "desc", "distinct", "do",
    "else", "end", "except", "false", "fetch", "for", "foreign", "from", "grant", "group", "having", "in",
    "initially", "intersect", "into", "lateral", "leading", "limit", "localtime", "localtimestamp", "not",
    "null", "offset", "on", "only", "or", "order", "placing", "primary", "references", "returning", "select",
    "session_user", "some", "symmetric", "system_user", "table", "then", "to", "trailing", "true", "union",
    "unique", "user", "using", "variadic", "when", "where", "window", "with",
}
